import React,{useState} from 'react';
import {createRoot} from 'react-dom/client';
import {SupportChat} from '../../src/components/common/CustomerLiveChat';
import '../../src/index.css';
import '../../src/components/layout/PublicShell.css';
const mode=new URLSearchParams(location.search).get('case');
const memory=new Map();const storage={getItem:key=>memory.get(key)??null,setItem:(key,value)=>memory.set(key,value)};
let current,pending=[],failSend=false,failJoin=false,failStart=mode==='offline',sendCount=0,joinCount=0,starts=0;
const createConnection=()=>{
 const handlers={};current={state:'Disconnected',on:(key,cb)=>{handlers[key]=cb;},off:key=>{delete handlers[key];},onclose:cb=>{handlers.close=cb;},onreconnecting:cb=>{handlers.reconnecting=cb;},onreconnected:cb=>{handlers.reconnected=cb;},start:async()=>{starts++;if(failStart){failStart=false;throw Error('isolated offline');}current.state='Connected';},stop:async()=>{},invoke:async(method)=>{if(method==='JoinCustomerGroup'){joinCount++;if(failJoin){failJoin=false;throw Error('join');}return;}sendCount++;return new Promise((resolve,reject)=>pending.push(()=>{if(failSend){failSend=false;reject(Error('isolated send failure'));}else resolve('accepted');}));},receive:(sender,text,id='fixture')=>handlers.ReceiveMessage?.(sender,text,id),disconnect:()=>{current.state='Reconnecting';handlers.reconnecting?.();},reconnect:async()=>{current.state='Connected';await handlers.reconnected?.();}};return current;
};
export function Fixture(){const[version,update]=useState(0),[identity,setIdentity]=useState(0);const refresh=()=>update(value=>value+1);return <><div style={{padding:12,fontSize:12,background:'#f1f5f9'}}><p>KIỂM THỬ CÁCH LY — không kết nối hoặc gửi tin tới người thật</p><div style={{display:'flex',gap:12,flexWrap:'wrap'}}>{[
 ['Cho phép phản hồi',()=>{pending.splice(0).forEach(resolve=>resolve());}],['Lỗi gửi kế tiếp',()=>{failSend=true;}],['Lỗi tên kế tiếp',()=>{failJoin=true;}],['Nhận trả lời',()=>current?.receive('[Admin] Hỗ trợ mẫu','Đây là phản hồi kiểm thử về sản phẩm.')],['Nội dung dài',()=>current?.receive('[Admin] Tên hỗ trợ thử nghiệm rất dài','Địa chỉ sản phẩm thử nghiệm '.repeat(30)+'X'.repeat(180))],['Mất kết nối',()=>current?.disconnect()],['Khôi phục kết nối',()=>void current?.reconnect()],['Đổi tài khoản',()=>setIdentity(value=>value+1)]
 ].map(([label,action])=><button style={{border:'1px solid #94a3b8',padding:8}} key={label} onClick={()=>{action();refresh();}}>{label}</button>)}</div><output style={{display:"block",overflowWrap:"anywhere"}} data-testid="fixture-state">{JSON.stringify({version,identity,starts,sendCount,joinCount,pending:pending.length})}</output></div><header className="public-header"><div className="public-header-inner"><a className="public-brand" href="#">Food<span>Delivery</span></a><div className="public-search"><input aria-label="Tìm sản phẩm" placeholder="Tìm sản phẩm…"/></div><div className="public-support"><SupportChat key={identity} createConnection={createConnection} storage={storage}/></div></div></header><main style={{padding:'48px 20px',minHeight:600}}><h1 style={{fontSize:28,color:'#064e3b'}}>Trang kiểm thử chat</h1><p>Dữ liệu trong hội thoại là minh họa kiểm thử.</p><button style={{padding:16,border:'1px solid #cbd5e1'}}>Tiếp tục mua sắm</button></main></>}
createRoot(document.getElementById('root')).render(<Fixture/>);
